<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap/app.php';
$user=pf_require_advertiser($pdo);
$q=$pdo->prepare("SELECT provider,provider_reference,amount,currency,status,created_at FROM pf_payment_orders WHERE advertiser_id=? ORDER BY id DESC LIMIT 30");$q->execute([(int)$user['id']]);$orders=$q->fetchAll();
$manual=$pdo->prepare("SELECT amount,currency,payment_method,payer_reference,status,created_at FROM pf_funding_requests WHERE advertiser_id=? ORDER BY id DESC LIMIT 20");$manual->execute([(int)$user['id']]);$manualRows=$manual->fetchAll();
?>
